import{_ as n,o as e,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const l=JSON.parse('{"title":"Giai đoạn 1 — đề xuất kỹ thuật","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/phase-1-design/plan.md","filePath":"feature/media-package-campaign/phase-1-design/plan.md"}'),o={name:"feature/media-package-campaign/phase-1-design/plan.md"};function r(d,t,c,h,s,g){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="giai-đoan-1-—-đe-xuat-ky-thuat" tabindex="-1">Giai đoạn 1 — đề xuất kỹ thuật <a class="header-anchor" href="#giai-đoan-1-—-đe-xuat-ky-thuat" aria-label="Permalink to &quot;Giai đoạn 1 — đề xuất kỹ thuật&quot;">​</a></h1><p>Theo <a href="./spec.html">spec.md</a>; A1–A3 được xác nhận 2026-10-08. Đây là contract để triển khai các giai đoạn sau. Không có migration/application code trong giai đoạn này.</p><h2 id="_1-campaign-trong-postgresql" tabindex="-1">1. Campaign trong PostgreSQL <a class="header-anchor" href="#_1-campaign-trong-postgresql" aria-label="Permalink to &quot;1. Campaign trong PostgreSQL&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field / nhóm</th><th>Đề xuất</th><th>Nguồn và quy tắc</th></tr></thead><tbody><tr><td>id</td><td>UUID, server generated</td><td>ID Campaign</td></tr><tr><td>workspaceMediaPackageId</td><td>UUID, required, UNIQUE, immutable</td><td>FK tới agreement; agreement.workspaceId đã UNIQUE nên đảm bảo một Campaign/Workspace</td></tr><tr><td>workspaceId</td><td>Trả trong DTO, suy ra từ agreement</td><td>Không cần lưu hai nguồn Workspace có thể lệch nhau</td></tr><tr><td>name</td><td>String, required, tối đa 255</td><td>Manager nhập</td></tr><tr><td>strategyDetail</td><td>Text, tối đa 10000</td><td>Có thể trống khi draft; bắt buộc trước approve</td></tr><tr><td>brandGuideline</td><td>Text, tối đa 10000, optional</td><td>Nội dung cho kế hoạch, không sửa Client profile</td></tr><tr><td>timeline</td><td>JSON object có startDate/endDate và milestones</td><td>Chốt timezone Workspace; các ngày ISO date, không suy mốc từ durationWeeks</td></tr><tr><td>packageTermsSnapshot / packageTermsVersion</td><td>JSONB / integer, server-only</td><td>Copy finalTerms/termsVersion khi tạo; immutable</td></tr><tr><td>deliverablePlan</td><td>JSONB</td><td>Các đầu ra của toàn gói, có ID ổn định và tổng số lượng; không có monthly allowance</td></tr><tr><td>workItems</td><td>JSONB array</td><td>Đầu việc tạo backlog, có ID ổn định; danh sách chưa đủ được lưu draft</td></tr><tr><td>contentVersion</td><td>Integer &gt;= 1</td><td>Tăng khi nội dung thay đổi thực sự; metadata vận hành không tăng</td></tr><tr><td>rowVersion</td><td>Optimistic-lock revision</td><td>Khác contentVersion; bảo vệ update/approve/deploy cạnh tranh</td></tr><tr><td>status</td><td>DRAFT / APPROVED / IN_PROGRESS / COMPLETED</td><td>Giữ enum hiện tại; triển khai riêng với deployment state</td></tr><tr><td>approvedByAgencyAt/Id/Version</td><td>Timestamp, actor UUID, integer</td><td>Duyệt phía Agency</td></tr><tr><td>approvedByClientAt/Id/Version</td><td>Timestamp, actor UUID, integer</td><td>Duyệt phía Client</td></tr><tr><td>completedAt / completedBy</td><td>Timestamp / UUID, server-only</td><td>Manager complete từ IN_PROGRESS</td></tr><tr><td>completionReason</td><td>Text &lt;= 2000</td><td>Bắt buộc, không chỉ whitespace, nếu còn Task chưa COMPLETED</td></tr><tr><td>completionTaskSummary</td><td>JSONB, server-only</td><td>Thống kê total/completed/unfinished ghi nhận tại thời điểm complete</td></tr><tr><td>createdAt / updatedAt</td><td>Timestamps</td><td>Audit</td></tr></tbody></table><p>Giữ các cột prototype allocations/allocation_period để tương thích đọc dữ liệu cũ. Luồng mới dùng tổng sản lượng; payload period mới phải bị từ chối thay vì âm thầm bỏ. Thêm dấu hiệu rõ <code>quantityBasis=TOTAL</code> trong catalogue và snapshot mới; nullable cho legacy. UI không yêu cầu chọn ba offeringModel cũ. Không tự đổi gói &quot;12 bài/tháng&quot; thành &quot;12 bài cả gói&quot;; phải nhận diện từng snapshot thiếu thời hạn và yêu cầu xử lý tường minh, không sửa agreement đã chốt.</p><p>Work item đề xuất: id (UUID), deliverableId, name (&lt;=255), type, dueDate (ISO instant). Tham chiếu deliverablePlan để truy vết; không tính sản lượng bằng số Work item vì một đầu ra có thể có nhiều bước thực hiện. Nếu đầu ra được tách thành nhiều đơn vị, đặt ID cho từng đơn vị/nhóm và phân bổ rõ, tránh cộng sản lượng lặp giữa các bước. Không dùng Task ID thay work item ID: Task chưa tồn tại trước deploy.</p><p>Campaign feedback lưu append-only record: id, campaignId, contentVersion, actorId, comment, createdAt. Approval audit và nội dung các phiên bản cần lưu bền vững (campaign_versions/approval events), không chỉ hai timestamp; version lưu snapshot đủ để đối chiếu và không đổi sau khi được approve. Nhận xét của Client không tăng contentVersion; Manager sửa mới tăng version/reset approvals atomically.</p><h2 id="_2-api-đe-xuat-cho-giai-đoan-2–4" tabindex="-1">2. API đề xuất cho giai đoạn 2–4 <a class="header-anchor" href="#_2-api-đe-xuat-cho-giai-đoan-2–4" aria-label="Permalink to &quot;2. API đề xuất cho giai đoạn 2–4&quot;">​</a></h2><p>Base: /api/v1/workspaces/{workspaceId}/campaigns. Giữ ApiResponse và X-Request-Id.</p><table tabindex="0"><thead><tr><th>Method/path</th><th>Payload chính</th><th>Quyền / kết quả</th></tr></thead><tbody><tr><td>GET base</td><td>—</td><td>Thành viên được xem; danh sách 0 hoặc 1 Campaign</td></tr><tr><td>POST base</td><td>name, strategyDetail?, brandGuideline?, timeline?, workItems?</td><td>Manager/Agency Owner hợp lệ; server chọn agreement APPROVED của Workspace; 201</td></tr><tr><td>GET /{id}</td><td>—</td><td>Kiểm tra id thuộc Workspace; 200</td></tr><tr><td>PATCH /{id}</td><td>expectedVersion, các field kế hoạch được phép</td><td>Manager; DRAFT; 200/409; không nhận status/approval/snapshot từ client</td></tr><tr><td>POST /{id}/feedback</td><td>contentVersion, comment</td><td>Client; 201; thông báo phía Agency</td></tr><tr><td>GET /{id}/feedback</td><td>pagination</td><td>Hai phía xem lịch sử</td></tr><tr><td>GET /{id}/versions</td><td>pagination</td><td>Hai phía xem phiên bản/diff</td></tr><tr><td>POST /{id}/approve</td><td>expectedVersion</td><td>Agency hoặc Client đúng Workspace; 200; thao tác lặp cùng phía/version không nhân đôi</td></tr><tr><td>POST /{id}/deploy</td><td>expectedVersion, idempotency key</td><td>Manager; APPROVED; đề xuất 202 cùng deployment ID hoặc kết quả hiện có</td></tr><tr><td>GET /{id}/deployment</td><td>—</td><td>Tiến trình/error/retry state, không lộ stack trace</td></tr><tr><td>POST /{id}/complete</td><td>expectedVersion, reason?</td><td>Manager; IN_PROGRESS; 200; reason required nếu có Task chưa COMPLETED</td></tr></tbody></table><p>API cũ /api/v1/media-campaigns cùng gọi service mới và cùng uniqueness/RBAC checks; không để client cũ vượt giới hạn. Gói chưa chốt không được tạo Campaign kể cả gọi route cũ. Không thêm approval-required state mới tùy tiện; one-sided approval vẫn DRAFT. No-op update không tăng contentVersion. Fully approved content immutable theo BA hiện hành.</p><p>Complete: server đọc Task Mongo theo campaignId và ghi summary/time/actor; Mongo lỗi thì không suy số Task bằng 0. Có unfinished và reason trống trả 400 field error. Không có unfinished thì reason optional. Request lặp khi đã COMPLETED trả bản hoàn thành hiện có, không ghi đè lý do/actor. Không có re-open endpoint trong scope này. Trạng thái COMPLETED của Campaign không khóa workflow Task con. Summary phản ánh lần đọc khi hoàn thành, không hứa transaction chung giữa PostgreSQL và Mongo.</p><h2 id="_3-mongo-task-va-specialist-content" tabindex="-1">3. Mongo Task và specialist content <a class="header-anchor" href="#_3-mongo-task-va-specialist-content" aria-label="Permalink to &quot;3. Mongo Task và specialist content&quot;">​</a></h2><p>Mongo tasks giữ fields V2: workspaceId, campaignId, campaignWorkItemId, type, name, dueDate, status, assigneeId, qcAssigneeId, requiresClientApproval, description, typeMetadata, sourceType/sourceRefId và timestamps. Bổ sung createdBy khi cần giữ tương thích editor. Mongo _id cho Task mới dùng UUID string canonical; API id vẫn UUID string. Không đổi _id tài liệu Mongo hiện hữu một cách ngầm định: phải inventory kiểu ID, refs và collisions trước khi thống nhất mapping cho dữ liệu legacy.</p><table tabindex="0"><thead><tr><th>Service</th><th>Task đề xuất</th><th>Nội dung chuyên biệt / trách nhiệm</th></tr></thead><tbody><tr><td>SOCIAL_POST</td><td>POST</td><td>Editor hiện tại; posts chỉ đại diện bài đã publish</td></tr><tr><td>LIVESTREAM_PREPARATION</td><td>LIVESTREAM</td><td>livestream_sessions; idea/script theo E51, không làm phát sóng</td></tr><tr><td>WORKSHOP_SUPPORT</td><td>SURVEY cho khảo sát</td><td>survey_forms/responses và Meet capability gắn Task theo E51-08d; xác nhận adapter với chủ module</td></tr><tr><td>EVENT_PLANNING</td><td>EVENT_PLAN</td><td>event_plans theo taskId; chỉ nội dung kế hoạch bàn giao</td></tr><tr><td>PRESS_RECOMMENDATION</td><td>PRESS_RECOMMENDATION</td><td>press_recommendations theo taskId; không thay danh bạ/tracking DA-949/950</td></tr></tbody></table><p>Contract tối thiểu cho hai collection mới: _id, taskId (unique), contentVersion, createdAt, updatedAt. event_plans thêm planContent (nội dung kế hoạch dạng text), referenceLinks[]; press_recommendations thêm recommendations[] gồm id, partnerName, websiteUrl?, rationale và notes. Thông tin đối tác chỉ là đề xuất, không booking, không tự tạo/cập nhật third_party_collaborators hoặc trạng thái hợp tác. Payload chuyên biệt được bổ sung ở bước Identify Detail/authoring, không bắt buộc khi deploy Task backlog. Schema form chi tiết được review cùng chủ E51 trước implementation.</p><p>Collection chuyên biệt không giữ workflow/assignee/status độc lập trùng với tasks. Thêm Task type cần review validator, enums, filters/views, approval, notification và publisher routing: chỉ POST được đưa vào pipeline publish hiện có. Không chỉ tạo collection.</p><h2 id="_4-noi-editor-hien-tai-voi-task-mongo" tabindex="-1">4. Nối editor hiện tại với Task Mongo <a class="header-anchor" href="#_4-noi-editor-hien-tai-voi-task-mongo" aria-label="Permalink to &quot;4. Nối editor hiện tại với Task Mongo&quot;">​</a></h2><p>Đề xuất ưu tiên: Mongo là nguồn Task; giữ Yjs operations/snapshots trong PostgreSQL, tham chiếu bằng UUID task_id. Đây là dữ liệu nội dung editor, không phải bản sao Task.</p><p>Bằng chứng code đã đọc:</p><ul><li>Task.java + TaskRepository hiện là JPA/JpaRepository&lt;Task, UUID&gt;.</li><li>TaskContentServiceImpl dùng TaskService.findTaskOrThrow, rồi truy vấn Yjs bằng UUID.</li><li>TaskController, TaskContentWebSocketController và REST/WS dùng UUID taskId.</li><li>Migration 2026-10-01-create-task-content-tables.sql đặt FK hai bảng nội dung tới PG tasks.</li><li>Content Writing UI tự POST tạo Task khi URL thiếu taskId; cần giữ tương thích hoặc thay entry flow cùng chủ module, không để mở Campaign Task lại sinh một Task khác.</li><li>WebSocket controller hiện chỉ lấy principal từ session rồi gọi appendOperation; handshake xác minh JWT, chưa thấy kiểm tra Workspace tại các entry point đã đọc.</li></ul><p>Các bước chuyển đổi cho giai đoạn 4, cần phối hợp chủ editor:</p><ol><li>Inventory PG tasks, mọi FK tới tasks, Mongo tasks/_id và refs từ approvals/posts; kiểm tra counts, UUID collision, orphan refs. Không chạy init/seed.</li><li>Backfill Task PG sang Mongo giữ nguyên UUID và timestamps/title→name. Không overwrite document trùng ID; sai Workspace/type là conflict phải dừng. Không suy tình trạng task cũ chỉ từ việc đã có Yjs content; quy tắc status mapping cần review dữ liệu.</li><li>Dùng maintenance window ngắn chặn ghi Task/editor; reconcile delta và counts. Sau verify mới cut over lookup/create sang Mongo. Trước cutover có thể bỏ bản backfill chưa dùng; sau cutover không rollback bằng cách trỏ lại PG đã lỗi thời.</li><li>Migration mới bỏ đúng FK từ bảng nội dung tới PG tasks, giữ NOT NULL/index và toàn bộ Yjs dữ liệu. Soft refs kiểm tra qua service Mongo và quyền Workspace. Không drop PG tasks ở lần đầu; giữ read-only để đối chiếu, không cho writer cũ chạy.</li><li>REST read/write/snapshot/restore và WS SEND/SUBSCRIBE cùng xác minh membership, Task Workspace/type và quyền hiện tại; không coi JWT hợp lệ là quyền với mọi Task.</li><li>Giữ wire DTO title như alias của name cho editor trong giai đoạn tương thích; GET content/version/restore và Yjs payload không đổi. Test các ID/URL cũ.</li><li>Chạy recovery, permission và editor regression trước bật Campaign deploy.</li></ol><p>Đây là thiết kế tích hợp, không tự sửa editor hoặc tháo FK trong giai đoạn 1. Rủi ro sequenceNumber đa tiến trình/snapshot đang thuộc editor phải review cùng chủ module; không gộp refactor toàn bộ CRDT vào task Campaign.</p><h2 id="_5-deployment-va-du-lieu-cu" tabindex="-1">5. Deployment và dữ liệu cũ <a class="header-anchor" href="#_5-deployment-va-du-lieu-cu" aria-label="Permalink to &quot;5. Deployment và dữ liệu cũ&quot;">​</a></h2><p>PostgreSQL transaction tạo deployment/outbox cùng campaign/contentVersion; worker dùng workItems snapshot đã duyệt. Sinh ID Task một lần hoặc xác định ổn định và giữ unique (campaignId, campaignWorkItemId); retry dùng set-on-insert, không update Task. Chỉ index tài liệu có hai trường hợp lệ; fail/reconcile nếu tồn tại duplicate cũ. Chỉ cập nhật Campaign IN_PROGRESS khi mọi insert được xác nhận; failure lưu retry state, không tạo lại campaign. Logs có requestId/campaignId/deploymentId, không token.</p><p>Trước constraint 1:1, báo các Workspace có nhiều Campaign. Không tự xóa/gộp. Mọi schema change có migration mới và init tương đương; không chạy trên Atlas ở giai đoạn 1.</p><h2 id="_6-ranh-gioi-ban-giao" tabindex="-1">6. Ranh giới bàn giao <a class="header-anchor" href="#_6-ranh-gioi-ban-giao" aria-label="Permalink to &quot;6. Ranh giới bàn giao&quot;">​</a></h2><p>DA-947: Campaign planning/schema/UI; DA-948: feedback/approval/deploy/complete. Task/editor thay đổi xuyên E51 phải thống nhất task/owner trước implementation; Post/Livestream/Survey/Meet chuyên biệt giữ owner trong master-plan. Task type mới nếu được chốt cần cập nhật AC E51 và phân công, không giả định thuộc DA-947 toàn bộ. Duplicate Workspace giai đoạn 5, không chặn Campaign planning. UI thêm namespace campaign vi/en và đăng ký locale theo cấu trúc hiện tại; kiểm tra light/dark/mobile.</p>',29)])])}const m=n(o,[["render",r]]);export{l as __pageData,m as default};
